package nb.pingpong.ping;

import android.util.Base64;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;

/**
 * Decodes the SubSource API keys that the build baked into {@link KeyData}.
 * <p>
 * KeyData is generated by Gradle from the SUBSOURCE_API_KEYS environment variable (see app/build.gradle); the
 * keys never appear as plain strings in the source, the APK or the DEX. This is obfuscation, not secrecy: the app
 * has to be able to read the keys to use them, so someone who reverse-engineers the code can still get them out.
 */
final class KeyVault {
    private KeyVault() {
    }

    /** All embedded keys, decoded. Empty if the build had no keys. */
    static List<String> keys() {
        List<String> out = new ArrayList<>();
        try {
            byte[] mask = Base64.decode(KeyData.B, Base64.DEFAULT);
            byte[] masked = Base64.decode(KeyData.A, Base64.DEFAULT);
            byte[] seed = new byte[masked.length];
            for (int i = 0; i < seed.length; i++) seed[i] = (byte) (masked[i] ^ mask[i % mask.length]);

            for (int i = 0; i < KeyData.E.length; i++) {
                byte[] cipher = Base64.decode(KeyData.E[i], Base64.DEFAULT);
                byte[] plain = new byte[cipher.length];
                MessageDigest sha = MessageDigest.getInstance("SHA-256");
                byte[] block = null;
                for (int p = 0; p < cipher.length; p++) {
                    if (p % 32 == 0) {
                        sha.reset();
                        sha.update(seed);
                        sha.update(new byte[]{(byte) (i >>> 8), (byte) i, (byte) (p / 32)});
                        block = sha.digest();
                    }
                    plain[p] = (byte) (cipher[p] ^ block[p % 32]);
                }
                String k = new String(plain, StandardCharsets.UTF_8).trim();
                if (!k.isEmpty()) out.add(k);
            }
        } catch (Exception ignored) {
            // corrupt / missing data: behave as "no keys"
        }
        return out;
    }
}
